practice.solution:
def column(A, j):
    return "(" + ", ".join(str(A[i][j]) for i in range(len(A))) + ")"

def paren(x):
    if x < 0:
        return f"({x})"
    return str(x)

def times(label, A, x):
    m, n = len(A), len(A[0])
    print(f"{label}: a {m}×{n} matrix times a vector with {len(x)} entries")
    if len(x) != n:
        print(f"  undefined: {n} columns need {n} weights")
        return
    b = [0] * m
    for j in range(n):
        for i in range(m):
            b[i] = b[i] + x[j] * A[i][j]
    parts = [f"{paren(x[j])}{column(A, j)}" for j in range(n)]
    print("  columns: " + " + ".join(parts) + " = (" + ", ".join(str(v) for v in b) + ")")
    rows = [sum(A[i][j] * x[j] for j in range(n)) for i in range(m)]
    print(f"  rows dotted with x: {rows}")

k = int(input())
for p in range(k):
    m, n = [int(t) for t in input().split()]
    A = [[int(t) for t in input().split()] for i in range(m)]
    x = [int(t) for t in input().split()]
    times(f"Problem {p + 1}", A, x)
